def eqn(n,key,latex,text):
    return dict(id=f'chem11-p{n}-{key}',latex=latex,accessible=text,formatSourceNotation=True,nativeLines={l:[[dict(text=text)]] for l in ('en','ur','ps')})
def pg(n,chapter,title,ur,ps,sid):
    s=page(n,chapter,title,ur,ps,sid); return s
def bullets(s,prefix,items,**m):
    for i,(e,u,p) in enumerate(items,1): add(s,f'{prefix}{i}',e,u,p,**m)

